package com.ianblk.zianmobs.client;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.components.*;
import java.nio.file.*;
import java.util.concurrent.atomic.AtomicReference;

/** Native screenshots and real transformed edge clicks; no player account or world. */
public final class StageEditorSmoke {
 private static int stage=-1,ticks,checks;private static JsonObject fixture;
 static void register(){if("true".equals(System.getenv("ZIAN_MOBS_STAGE_CLIENT")))net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(StageEditorSmoke::tick);}
 private static void check(boolean b,String label){if(!b)throw new IllegalStateException(label);checks++;}
 private static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(mc.screen==null||mc.getOverlay()!=null)return;try{if(stage<0){check(mc.gameDirectory.toPath().toAbsolutePath().toString().contains("stage-client-smoke"),"isolated client required");fixture=JsonParser.parseString(Files.readString(Path.of(System.getenv("ZIAN_MOBS_STAGE_FIXTURE")))).getAsJsonObject();stage=0;mc.options.pauseOnLostFocus=false;open(mc);return;}if(++ticks<25)return;ticks=0;check((int)mc.getWindow().getGuiScale()==2+stage/10,"native GUI scale");Screenshot.grab(mc.gameDirectory,"stages-"+stage+".png",mc.getMainRenderTarget(),c->{});if(++stage<30)open(mc);else{Files.writeString(mc.gameDirectory.toPath().resolve("stage-client-pass.txt"),"PASS: "+checks+" checks, 30 native screenshots at GUI scales 2/3/4; real transformed clicks on button borders; add, reorder, remove, boss selection, per-creature removal, draft apply and cancel verified.\n");mc.stop();}}catch(Throwable error){com.ianblk.zianmobs.ZianMobs.LOGGER.error("STAGE_CLIENT_SMOKE_FAILED",error);try{Files.writeString(mc.gameDirectory.toPath().resolve("stage-client-failed.txt"),error.toString());}catch(Exception ignored){}mc.stop();}}
 private static Button find(Screen screen,String text){return screen.children().stream().filter(c->c instanceof Button b&&b.getMessage().getString().equals(text)&&b.active).map(c->(Button)c).findFirst().orElseThrow(()->new IllegalStateException("Button not available: "+text));}
 private static void click(Minecraft mc,String text){click(mc,find(mc.screen,text));}
 private static void click(Minecraft mc,Button button){var screen=mc.screen;int minHeight=screen instanceof EncounterStagesScreen||screen instanceof MobsScreen||screen instanceof EntitySelectorScreen?400:360;var layout=ResponsiveLayout.fit(mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),600,minHeight);check(screen.mouseClicked(layout.x()+(button.getX()+0.2)*layout.scale(),layout.y()+(button.getY()+0.2)*layout.scale(),0),"button edge accepted "+button.getMessage().getString());}
 private static void open(Minecraft mc)throws Exception{mc.options.guiScale().set(2+stage/10);mc.resizeDisplay();var classic=JsonParser.parseString(Files.readString(Path.of(System.getenv("ZIAN_MOBS_STAGE_FIXTURE")).resolveSibling("classic-zone.json"))).getAsJsonObject();var form=new MobsScreen((stage%10==0||stage%10==1||stage%10>=4?classic:fixture).deepCopy());mc.setScreen(form);if(stage%10==0){check(form.children().stream().filter(c->c instanceof EditBox).count()==2,"classic-basic-name-and-wave-count-visible");return;}if(stage%10>=8){String file=stage%10==8?"companions-named.json":"companion-name.json";var namesView=JsonParser.parseString(Files.readString(Path.of(System.getenv("ZIAN_MOBS_STAGE_FIXTURE")).resolveSibling(file))).getAsJsonObject();if(stage%10==8){mc.setScreen(new CompanionScreen(namesView));check(mc.screen.children().stream().anyMatch(c->c instanceof Button b&&b.getMessage().getString().equals("Cambiar nombre")&&b.active),"rename available to ordinary owner");}else{mc.setScreen(new MobsScreen(namesView));var box=(EditBox)mc.screen.children().stream().filter(EditBox.class::isInstance).findFirst().orElseThrow();check(box.getValue().equals("Luna ✨"),"saved nickname in editor");box.setValue("Pequeña Estrella");check(box.getValue().equals("Pequeña Estrella"),"nickname editor accepts Spanish");}return;}if(stage%10>=6){var mobView=JsonParser.parseString(Files.readString(Path.of(System.getenv("ZIAN_MOBS_STAGE_FIXTURE")).resolveSibling("entity-mob.json"))).getAsJsonObject();var choices=mobView.getAsJsonArray("fields").asList().stream().map(JsonElement::getAsJsonObject).filter(f->f.get("key").getAsString().equals("entity")).findFirst().orElseThrow().getAsJsonArray("choices");mc.setScreen(new EntitySelectorScreen(form,choices,id->mc.setScreen(form)));check(mc.screen.children().stream().anyMatch(c->c instanceof Button b&&b.getMessage().getString().equals("Hostiles y modelos de dungeon")&&!b.active),"hostiles selector is default");if(stage%10==7)click(mc,"Otros mobs compatibles");return;}if(stage%10>=4){click(mc,stage%10==4?"Tamaño":"Puntos");return;}click(mc,"Encuentro");if(stage%10==1)return;var field=fixture.getAsJsonArray("fields").asList().stream().map(JsonElement::getAsJsonObject).filter(f->f.get("kind").getAsString().equals("stages")).findFirst().orElseThrow();var mobs=field.getAsJsonArray("choices");var bosses=field.getAsJsonArray("bossChoices");String before=fixture.getAsJsonObject("values").get("stages").getAsString();var result=new AtomicReference<String>();java.util.function.Consumer<String> accept=v->{result.set(v);mc.setScreen(form);};
  mc.setScreen(new EncounterStagesScreen(form,mobs,bosses,before,accept));click(mc,"↓");click(mc,"Usar estas etapas");check(JsonParser.parseString(result.get()).getAsJsonArray().get(0).getAsJsonObject().get("kind").getAsString().equals("WAVE"),"reorder changes first stage");
  mc.setScreen(new EncounterStagesScreen(form,mobs,bosses,before,accept));click(mc,"Añadir oleada");click(mc,"Añadir mob");var mobSearch=(EditBox)mc.screen.children().stream().filter(EditBox.class::isInstance).findFirst().orElseThrow();mobSearch.setValue("Guardia de la Fortaleza");click(mc,"Guardia de la Fortaleza");click(mc,"Usar selección");click(mc,"Usar estas etapas");check(JsonParser.parseString(result.get()).getAsJsonArray().size()==4,"wave appended");
  mc.setScreen(new EncounterStagesScreen(form,mobs,bosses,before,accept));click(mc,"Añadir jefe");check(mc.screen instanceof ChoiceScreen,"boss chooser opened");var search=(EditBox)mc.screen.children().stream().filter(EditBox.class::isInstance).findFirst().orElseThrow();search.setValue("Señor del Umbral");click(mc,"Señor del Umbral");click(mc,"Usar estas etapas");check(JsonParser.parseString(result.get()).getAsJsonArray().size()==4,"boss appended");
  mc.setScreen(new EncounterStagesScreen(form,mobs,bosses,result.get(),accept));click(mc,"Quitar");click(mc,"Confirmar");click(mc,"Usar estas etapas");check(JsonParser.parseString(result.get()).getAsJsonArray().size()==3,"selected stage removed");
  mc.setScreen(new EncounterStagesScreen(form,mobs,bosses,before,accept));click(mc,"↓");mc.screen.onClose();check(mc.screen instanceof ManagerConfirmScreen,"discard prompt");click(mc,"Cancelar");check(mc.screen instanceof EncounterStagesScreen,"cancel retains draft");
  if(stage%10==2){mc.setScreen(new EncounterStagesScreen(form,mobs,bosses,before,accept));return;}
  var teamResult=new AtomicReference<String>();mc.setScreen(new TeamScreen(form,mobs,"stage_guard,stage_boss,stage_guard",teamResult::set));click(mc,"×");click(mc,"Usar selección");check(teamResult.get().equals("stage_boss,stage_guard"),"specific creature removed without losing others");mc.setScreen(new TeamScreen(form,mobs,"stage_guard,stage_guard",v->mc.setScreen(form)));
 }
}
